​
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();

        int first = 2;
        int last = 2 + 3 * (n - 1);

        // 使用等差数列求和公式
        int sum = (first + last) * n / 2;
        System.out.println(sum);
    }
}
