js:
const readline = require('readline');
​
// 创建接口读取标准输入
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
rl.on('line', (line) => {
    const n = parseInt(line.trim());
​
    let first = 2;
    let last = 2 + 3 * (n - 1);
​
    // 使用等差数列求和公式
    let sum = (first + last) * n / 2;
    console.log(sum);
​
    rl.close();
});
